def subtract(a, b):
    def merge_intervals(intervals):
        """Merge overlapping/touching intervals into disjoint ones."""
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Disjoint, add new interval
                merged.append([start, end])

        return merged

    def subtract_one(intervals, subtract_iv):
        """Subtract one interval from a list of intervals."""
        result = []
        sub_start, sub_end = subtract_iv

        for start, end in intervals:
            # No overlap
            if end <= sub_start or start >= sub_end:
                result.append([start, end])
            else:
                # There is overlap, keep the parts that don't overlap
                if start < sub_start:
                    result.append([start, sub_start])
                if end > sub_end:
                    result.append([sub_end, end])

        return result

    # Merge intervals in a
    a_merged = merge_intervals(a)

    # Merge intervals in b
    b_merged = merge_intervals(b)

    # Subtract all b intervals from a
    result = a_merged
    for b_iv in b_merged:
        result = subtract_one(result, b_iv)

    return result

